quests[50837] = { id = 50837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kurzer Überflug", description = "Malfurion ist klar, dass seine Irrwischmauer nur ein Provisorium ist. Er verschafft sich Zeit, bis Verstärkung in Teldrassil eintrifft.\n\nWir müssen unbedingt einen Weg durch diese Mauer finden, und das schnell.\n\nIch möchte, dass Ihr unsere Sprengstoffreserven nehmt und etwas Druck ausübt. Ihr werdet die Mauer nicht völlig einreißen können, aber vielleicht findet Ihr ja eine Öffnung für uns. Ich lasse einen Trupp bereitstehen, der zuschlagen kann, sobald Ihr einen Weg gefunden habt.\n\nZarvik Bummfix wird Euch ein paar Bombardiere zur Verfügung stellen können.", sourceObjective = "Benutzt Sprengstoff, um die Armee der Allianz von der Dunkelküste zu vertreiben.", completion = "Wie ist es gelaufen?", sourceObjectiveStatus = "unverified-source-field" }
quests[50838] = { id = 50838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für Ptrobleme", description = "Ah, Ihr habt also gemerkt, dass er schon wieder ausgebüxt ist.\n\nDiesma' würd ich im Osten such'n. Aus der Richtung hab ich Gekreische gehört.\n\nEs geht ihm bestimmt gut. Was kann ihm auch schon groß passier'n, wenn Ihr auf ihn aufpasst?\n\n<Schwingenhalter Goja lächelt ein klein wenig spöttisch.>\n\nGeht einfach un' findet es raus.", sourceObjective = "Findet Kua'fon in Atal'Gral und rettet ihn vor Gefahren.", completion = "<Kua'fon untersucht beiläufig seine Schwingen auf Verletzungen. Er wirkt ziemlich selbstgefällig.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50839] = { id = 50839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKRIIIII!", description = "<Kua'fon öffnet das Mäulchen und stößt ein langanhaltendes Kreischen aus.>\n\nSKRIIIIIIIII!!!\n\n<Ihr wisst, was zu tun ist.>", sourceObjective = "Füttert Kua'fon.", completion = "<Kua'fon gluckst zufrieden.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50841] = { id = 50841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SKRIIIII!", description = "<Kua'fon öffnet das Mäulchen und stößt ein langanhaltendes Kreischen aus.>\n\nSKRIIIIIIIII!!!\n\n<Ihr wisst, was zu tun ist.>", sourceObjective = "Füttert Kua'fon.", completion = "<Kua'fon leckt sich über die Lippen und bewegt seinen Kopf zufrieden auf und ab.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50842] = { id = 50842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masthocker", description = "Kua'fon hat sich wieder ma' zu weit vorgewagt un' is' die Klippe runtergefall'n.\n\nNormalerweise schafft er's allein zurück, aber diesma' dauert's zu lang.\n\nGeht lieber runter zum Strand un' sucht nach ihm. Wahrscheinlich hängt er auf einem der Schiffsmast'n da drauß'n fest.\n\nWenn er nich' runterkomm' will, könnt Ihr versuch'n, ihn mit Fisch zu überzeug'n.", sourceObjective = "Findet Kua'fon in Talanjis Tadel und lockt ihn mit Fisch herunter.", completion = "<Kua'fon stochert mit einer Schwingenklaue in seinen Zähnen herum und vermeidet sorgfältig jeglichen Augenkontakt mit Euch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50845] = { id = 50845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kul'krazahn" }
