quests[50859] = { id = 50859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kandak" }
quests[50860] = { id = 50860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gespür für Ptrobleme", description = "Kua'fon is' ziemlich groß geword'n. Vielleicht meint er, den Tier'n im Dschungel ebenbürtig zu sein.\n\nEr wird lernen müss'n, dass er das nich' is'. Ihr solltet ihn schnell find'n, bevor er diese Lektion mit seinem Leb'n bezahlt.\n\nSucht im Nord'n, von da hab ich irgend'nen Tumult gehört.", sourceObjective = "Findet Kua'fon in den Wilden Landen und rettet ihn.", completion = "<Kua'fon breitet seine Schwingen aus und stößt einen durchdringenden Schrei aus. Er hatte die ganze Zeit alles unter Kontrolle.>\n\nSkrii!", sourceObjectiveStatus = "unverified-source-field" }
