quests[50877] = { id = 50877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'ralka" }
quests[50878] = { id = 50878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unklare Sicht", description = "Seht nach oben.\n\nSeht Ihr sie, überall in den Bäumen? Diese hell leuchtenden Eulen sind keine lebenden, atmenden Waldbewohner... Das ist Magie der Kaldorei. Es sind Wächter, die Malfurion alles berichten, was sie sehen.\n\nSo etwas sollten wir nicht dulden, oder was meint Ihr?\n\nKümmert Euch darum, {name}. Aber seht Euch vor, es sind nicht die einzigen Feinde im Wald.\n\nNichts und niemand darf uns jetzt aufhalten.", sourceObjective = "Eliminiert die Wächtereulen in den Bäumen und tötet die rasenden Furbolgs der Dunkelküste.", completion = "Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50879] = { id = 50879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hölzerne Spione", description = "Wenn die Augen des Waldes geschlossen sind, verbleibt noch eines: die Ohren. Die Urtume. \n\nSie spüren die Erschütterungen unserer Schritte und melden Malfurion all unsere Bewegungen.\n\nIst Eure Fackel bereit?", sourceObjective = "Besiegt das brennende Urtum.", completion = "Kommt Champion. Lasst uns in diesen uralten Hain einnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50880] = { id = 50880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unaufhaltbare Macht", description = "Wir müssen jetzt zuschlagen, {name}. \n\nDurch die Mauer zu gelangen wird nicht einfach, aber Ihr werdet es schon schaffen. Tut, was Ihr dazu tun müsst, und trefft Euch mit mir auf der anderen Seite. Ich werde mit einem Trupp zäher Soldaten und so vielen Verwüstern kommen, wie den Durchgang überleben.\n\nVielleicht schaffen wir es heute noch nicht nach Darnassus, aber der Ausgang des Krieges hängt nicht von einem Sieg allein ab, sondern von den vielen tausend kleinen Siegen.\n\nAlso, kann es losgehen?", sourceObjective = "Haltet die Allianztruppen an der Dunkelküste auf.", completion = "Malfurion wird mit seinen Truppen zurückkehren, aber bis dahin werden wir weitermachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50881] = { id = 50881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Königlicher Bericht", description = "In der Stadt wirk'n sie Blutmagie, Wach'n verschwind'n un' unsre oberste Spionin Yazma verhält sich verdächtig. Darüber müss'n wir Rastakhan unterricht'n, ohne dass Yazma sich einmisch'n kann.\n\nRastakhan is' glücklicherweise 'n kluger König un' seine Gegner vergess'n das oft.\n\nIch hab 'nen Bericht verfasst un' in 'nem Code geschrieb'n, den Rastakhan selbst angefertigt hat un' den nur er, ich un' mein Bruder Habutu kenn'. Bringt ihn zu Habutu. Er wird dafür sorg'n, dass der König alles erfährt.", sourceObjective = "Bringt Zolanis Bericht zu Habutu am Goldenen Thron.", completion = "Hm. Zolani hat Euch sehr gelobt. Vielleicht müss'n wir Euch jetzt noch nich' umbring'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50882] = { id = 50882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts als Asche", description = "Während unseres gesamten Feldzugs habe ich verstanden, was der Kriegshäuptling hier vorhat. Ich sah ihre Strategie... glaubte, dass es keinen anderen Weg gibt.\n\nWürde Darnassus der Horde gehören, wäre die Allianz wie gelähmt. Wut und Angst würden sich wie Maden an ihren Herzen laben, bis sie wie totes Holz zerbrechen und zersplittern.\n\nAber... das hier wird sie vereinen. Und sie werden kommen.\n\nKehrt nach Unterstadt zurück, {name}. Sprecht mit dem Kriegshäuptling. Wir müssen auf uns das Kommende vorbereiten.", sourceObjective = "Sprecht mit Kriegshäuptling Sylvanas Windläufer in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50885] = { id = 50885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lei-zhi" }
quests[50886] = { id = 50886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzschwinge", description = "Es ist nicht meine Art, die Jungen meiner Brut zu beglucken. Aber für Euren Kleinen will ich eine Ausnahme machen.\n\nIch habe ja gesehen, wie Ihr Euch um ihn gekümmert habt. Und es wäre ja eine Schande, wenn Eure... Mühen... umsonst gewesen sein sollten.\n\nBegebt Euch nach Zuldazar und findet etwas, das als Ersatzschwinge für Euren Kleinen fungieren kann.\n\nSchwingenhalter Goja wird dann wissen, was als Nächstes zu tun ist. Sprecht mit ihm, wenn Ihr das Ding habt.", sourceObjective = "Besorgt einen riesigen Papierdrachen.", progress = "Hat Pa'ku guten Rat gegeb'n?", completion = "Was is' das?\n\n<Schwingenhalter Goja schaut zwischen Euch und dem Pterrordax hin und her.>\n\nOh, verstehe!", sourceObjectiveStatus = "unverified-source-field" }
quests[50887] = { id = 50887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ptrau dich", description = "Ihr sollt wiss'n, dass das sehr ungewöhnlich für Pa'ku ist. Sie wirft ihre Schützlinge gern ins kalte Wasser. Oder in dem Fall in die Luft.\n\nWas? Das stimmt.\n\nDiese Methode könnte funktionier'n. Manchmal zieh'n Pterrordaxmütter ihre Jungen einfach aus'm Nest und halt'n sie mit den Krallen in der Luft, bis sie sich trau'n, die Schwingen auszubreit'n.\n\nUnd da das Junge keine Mutter hat, verwendet Ihr dazu eben 'nen Drachen.\n\nPa'ku hat 'ne Route vorgeben, der Ihr folg'n müsst.\n\nLegt 'nen ruhigen Flug hin, damit Euer Pterrordaxjunges nicht noch mehr Angst kriegt!", sourceObjective = "Steigt auf den riesigen Papierdrachen auf und nehmt Euren Pterrordax mit auf einen Flug, damit er Selbstvertrauen aufbauen kann.", completion = "<Pa'ku schaut das Junge missbilligend an.>\n\nSicher, dass wir ihn nächstes Mal nicht einfach werfen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[50897] = { id = 50897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerrückstoß", description = "<Als Standardausrüstung liefern die Goblins der Horde Flammenwerfer, um den Schnee zu beseitigen.>\n\n<Dieser hier ist zwar etwas abgenutzt, könnte aber noch dazu taugen, ein paar Minengerätschaften der Goblins zu zerstören.>", sourceObjective = "Zerstört 6 Goblinmaschinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50899] = { id = 50899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht mit mir, Troll" }
quests[50900] = { id = 50900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spätzünder", description = "<Pa'ku blickt auf das Pterrordaxjunge nieder.>\n\nAlso, mir gehen die Ideen aus. Mein Sohn wird Euch zurück zum Nest bringen. Und keine Sorge: ER kann fliegen.\n\nEUER Junges dagegen muss seinen Weg allein zurückfinden. Das stärkt seinen Charakter.\n\nVielleicht können wir diese absurde Schwachstelle ja beizeiten beheben.", sourceObjective = "Kehrt zum Nest an der Pterrorhöhe zurück.", completion = "Pa'ku ist die Herrin der Winde. Is' doch klar, dass sie da von ihrer Brut erwartet, dass sich alle für das Fliegen begeistern.\n\nAuch Euer Junges wird's schaff'n. Es braucht wohl nur 'n bisschen länger als andre.", sourceObjectiveStatus = "unverified-source-field" }
quests[50901] = { id = 50901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saurid à la Surprise", description = "Die Sande von Vol'dun stecken voller brutaler Kreatur'n, aber keine is' so brutal wie die, die von den Zandalari kommen.\n\nEiner dieser Kriminell'n befindet sich gleich hier in Glutsand. Er heißt Sezahjin und war früher mal der Küchenchef des Königs. Hat er Euch von seinem berühmt'n Gericht \"Saurid à la Surprise\" erzählt? Ratet mal, welche Hauptzutat es hat.\n\nEr is' tief gesunken, aber für Jani nich' tief genug. Er muss seinen Stolz verlier'n.\n\nAchtet nur drauf, dass Euch die Kreaturen der Sande nich' seh'n.", sourceObjective = "Überlebt Janis Streich für Sezahjin.\n\nWenn Ihr Eure Sauridenverkleidung verliert, kehrt zu Jani zurück und besorgt Euch eine neue.", completion = "Haha! Gut gemacht, Zastamann. Er findet bestimmt 'ne neue Mütze, aber Ihr habt die, die er getrag'n hat, als er sein Saurid à la Surprise gekocht hat. Ihr seid in meiner Gunst gestieg'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50903] = { id = 50903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister vermisst", description = "Meister Eschtal wollte, dass ich ein paar Heilvorräte hole, und ich war gerade auf dem Weg zu Bürgermeister Reinwald, als diese Dinger die Stadt angriffen. Der Meister hat es nicht hinter die Barrikade geschafft.\n\nAber falls er lebt - und er ist verrückt genug, um so etwas zu überleben - hat er sich wahrscheinlich in seiner Hütte verschanzt. Mit irgendwelchen ätzenden Substanzen. Und Sprengstoff.\n\nWie wäre es, wenn Ihr mal im Keller nachschaut und ich außerhalb des Detonationsradius... also im Garten am besten.\n\nUnd macht besser keinen allzu brennbaren Eindruck.", sourceObjective = "Findet Meister Eschtal.", progress = "Oh! Ihr seid ja gar nicht eines dieser Monster! Habt Ihr diese Unholde erledigen können?", completion = "Ich bin Euch für Eure Hilfe bei der Befreiung der Stadt sehr dankbar! Ich habe mir wegen dieser merkwürdigen Monster schon richtig Sorgen gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50904] = { id = 50904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verwaiste Passage", description = "Mein Volk kennt diesen uralten Durchgang schon seit Generationen, aber bis jetzt hat es noch niemand gewagt, ihn zu betreten.\n\nDer Tunnel führt zum Grab von Mythrax dem Auflöser, und es heißt, dass seine Macht noch immer seine Höhle erfüllt. Niemand weiß, welche Schrecken uns darin erwarten...\n\nOffenbar sind Eure Freunde bereits hineingegangen, um Jakra'zet daran zu hindern, Mythrax von den Toten auferstehen zu lassen.\n\nUns läuft die Zeit davon. Wir müssen Kaja und Rakera finden, bevor sie Jakra'zet allein angreifen!", sourceObjective = "Findet Klingenwache Kaja und Kriegswache Rakera in Atul'Aman.", completion = "Jakra'zet hat bereits mit dem Ritual begonn'n. Wir müss'n ihn aufhalt'n, bevor's zu spät is'!", sourceObjectiveStatus = "unverified-source-field" }
quests[50908] = { id = 50908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riecht nach Ärger", description = "Die Horde hat in Brennadam eine Menge Blut vergossen. Es wird trotzdem Zeit, dass noch mehr vergossen wird.\n\nDer Geruch von Blut lässt die Raubtiere in diesen Hügeln durchdrehen. Wir nutzen es bei der Jagd, um Tiere anzulocken.\n\nDie Truppen der Horde haben Höhlen oben in den Hügeln besetzt. Werft diese Geruchsphiolen in die Höhlen, in denen die Truppenkommandanten ihre Angriffe koordinieren. Der Geruch sollte sämtliche Raubtiere des Hügels zu ihnen locken!", sourceObjective = "Tötet die Truppenkommandanten Ogarth und Durmok.", completion = "Solange Ihr hier seid, werden sie es nicht noch einmal versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50909] = { id = 50909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptsache gut bewaffnet", description = "Das ist jetzt unser neues Zuhause und wir werden kämpfen, um es zu behalten!\n\nWir sind vielleicht nicht viele, aber wir werden uns bis an die Zähne bewaffnen.\n\nSammelt für unsere Rebellion jede Axt, jedes Schwert, jeden Speer, jede Armbrust und jede Schusswaffe ein, die Ihr finden könnt!", sourceObjective = "Findet 15 Rebellenwaffen.", progress = "Wir brauchen mehr als das. Besorgt uns ein paar Waffen!", completion = "Das ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[50910] = { id = 50910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Jagd", description = "Mit der Horde kommen wir zurecht, aber heute haben wir durch eine Gruppe Meuchelklingen der Verlassenen zwei Leute verloren. Wir hatten Probleme, sie zu verfolgen, daher könnten wir Eure Hilfe gut brauchen.\n\nEs sind verstohlene, gefährliche Kämpfer, also zeigt keine Gnade.", sourceObjective = "Säubert die Hügel von den Meuchelklingen der Verlassenen.", completion = "Eure Fähigkeiten sind beeindruckend. Ich glaube nicht, dass einer von uns diese Meuchelklingen so leicht hätte ausschalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[50911] = { id = 50911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einer gegen die Horde", description = "Als es brenzlig wurde, haben ich und ein paar Freunde versucht, einigen Leuten bei der Flucht aus Korlach zu helfen, damit sie sicher nach Aroms Wehr gelangen. Ich habe eine Bewegung oben auf dem Hügel bemerkt, also bin ich zurückgegangen, um das zu überprüfen. Als wäre die dem Wahnsinn verfallene Stadt nicht schlimm genug, haben wir jetzt noch ein weiteres Problem.\n\nDie Horde.\n\n<Melzer spuckt aus.>\n\nFür diese Narren gibt es in unserem Land keinen Platz. Tränkt den Schnee mit ihrem Blut.", sourceObjective = "Tötet 10 Einheiten der Horde.", completion = "Nur ein toter Orc ist ein guter Orc.", sourceObjectiveStatus = "unverified-source-field" }
quests[50912] = { id = 50912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zündender Einfall", description = "<Eine Goblinbergbaumaschine ragt halb aus dem Schnee heraus.>\n\n<Obwohl sie halb begraben ist, wirkt sie noch funktionsfähig. Wenn Ihr nur den Schlüssel hättet.>", sourceObjective = "Findet den Zündschlüssel.", progress = "<Die Maschine liegt reglos im Schnee.>", completion = "<Mit etwas Mühe gelingt es Euch, die Maschine aus dem Schnee zu befreien. Als Ihr den Schlüssel benutzt, springt sie surrend an.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50913] = { id = 50913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen von Akunda", description = "Ihr habt Euch meines Segens würdig erwiesen, {name}.\n\nWenn Ihr mich nun als Loa erwählt, könnt Ihr meine Macht nutzen, wann immer Ihr sie braucht.\n\nHaltet Zwiesprache an meinem Schrein, um mein Geschenk zu empfangen.\n\nWisset, dass egal wie Ihr Euch auch entscheiden mögt, Ihr in diesen Mauern immer ein willkommener Gast sein werdet.", sourceObjective = "Haltet Zwiesprache an Akundas Schrein.", progress = "Ich erteile meinen Anhängern meinen Segen.", completion = "Falls Ihr jemals meiner Gabe bedürft, haltet Zwiesprache an einem Schrein, der mir zu Ehren errichtet wurde, und Ihr sollt meinen Segen empfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50929] = { id = 50929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit für alle", description = "Der Hordenabschaum dort auf dem Hügel baut ein Erz ab, das ich noch nie gesehen habe.\n\nWenn sie den weiten Weg hergekommen sind, um danach zu suchen, muss es wertvoll sein. Nehmt, so viel Ihr finden könnt!", sourceObjective = "Sammelt Azerit aus 6 Kisten.", progress = "Konntet Ihr herausfinden, was sie da oben gemacht haben?", completion = "Das sieht wie ein Haufen Müll aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[50930] = { id = 50930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallen mit Stil", description = "<Kua'fon blickt zu dem Drachen und zurück zu Euch. Dann blickt er wieder zum Drachen und streckt seinen Kopf gezielt nach vorne. Langsam wandert sein Blick zurück zu Euch.>\n\nSkrii.\n\n<Zeit für einen weiteren Flug!>", sourceObjective = "Nehmt Kua'fon mit auf einen weiteren Flug auf dem riesigen Papierdrachen.", completion = "Noch 'n erfolgreicher Flug! Ich hoff, Kua'fon gewöhnt sich mit der Zeit dran, dass der Himmel sein Zuhause is'.\n\nUnd keine Sorge, er wird's von allein wieder hoch ins Nest schaff'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50933] = { id = 50933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bedauernswerter Vorfall", description = "<Ihr habt keine Mittel, um die Leiche zu identifizieren, aber die Kleidung deutet auf einen Angehörigen der kaiserlichen Wache aus Zuldazar hin.\n\nBei einer flüchtigen Durchsuchung des Gebiets entdeckt Ihr eine Blutspur, die nach Westen führt. Vielleicht könnt Ihr die Todesursache herausfinden, wenn Ihr der Spur folgt.>", sourceObjective = "Findet heraus, was mit der kaiserlichen Wache passiert ist.", completion = "Ihr seht nich' aus, wie 'n Gefangener. Ich... Ich könnte Eure Hilfe brauch'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50934] = { id = 50934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zufällige Sichtung", description = "Einer der Späher sagte, er hätte ein paar Bluttrolle gesehen, die auf der anderen Flussseite einen Zandalari verfolgten.\n\nEr schien die gleiche Kleidung zu tragen wie Eure Gruppe. Wieso habt Ihr Leute hier ständig Ärger?\n\nIch markiere auf Eurer Karte die Stelle, an der man ihn zuletzt gesehen hat. Bringt mir nur nicht eine Horde Bluttrolle hier herüber, verstanden?", sourceObjective = "Untersucht die Angelegenheit des vermissten Zandalari.", completion = "<Das Leben des Zandalari hängt am seidenen Faden. Neben ihm liegt ein Gegengift.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50936] = { id = 50936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überlebensstrategie" }
quests[50940] = { id = 50940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit der Flügellosen", description = "<Kua'fon keucht und zittert vor Erschöpfung.>\n\nDas führt zu nichts. Vielleicht ist es Zeit, jemanden ohne Flügel um Rat zu fragen.", sourceObjective = "Sucht Hexfürst Raal auf.", completion = "Ich hab das Kreisch'n gehört. Schön, Euch in einem Stück wiederzuseh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[50942] = { id = 50942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angemessene Kleidung", description = "Wenn Kua'fon es mit dem Flieg'n ernst meint, werd'n wir ihn schütz'n müss'n.\n\nGeht und besorgt 'nen Berserkerschädel und einige Rüstungsteile für ihn. Ihr könnt mich danach unt'n in Talanjis Tadel treff'n. Dann werd'n wir ihn gebührend einkleid'n.", sourceObjective = "Besorgt einen Berserkerschädel und einen leichten Himmelsschreckenharnisch.", progress = "Habt Ihr die Sach'n, um die ich Euch gebet'n hatte?", completion = "Vielleicht wird sich Euer Begleiter jetzt nich' mehr vor seinem nächst'n Fall fürcht'n. Haha!", sourceObjectiveStatus = "unverified-source-field" }
quests[50943] = { id = 50943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Freuden des Fliegens", description = "Bereit, {name}?\n\nKua'fon is' bereit zu flieg'n. Ob er's auch wirklich kann, is' 'ne andre Frage, aber wie auch immer, ich seh euch beide dann im Horst.\n\nSteigt auf un' führt ihn. Ich glaub nich', dass er durch diesen Schädel viel seh'n kann.\n\nAta und ich werd'n Euch den Weg zeig'n.", sourceObjective = "Folgt Hexfürst Raal und fliegt mit Kua'fon zurück zum Nest.", completion = "<Kua'fon keucht vor Anstrengung, scheint aber mit seinen Bemühungen zufrieden zu sein.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[50944] = { id = 50944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fix, aber nicht fertig", description = "<Kua'fon zappelt begeistert in seiner neuen Rüstung. Er beginnt, rastlos hin und her zu laufen. Die flugunfähige Kreatur scheint Geschmack an Abenteuern gefunden zu haben.>\n\nSkrii! Skrii!", sourceObjective = "Akzeptiert Kua'fon als Euren neuen Reisegefährten.", completion = "<Kua'fon senkt seinen Kopf und stupst Euch sanft an. Er ist bereit, Euch überallhin zu folgen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50953] = { id = 50953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grünpirscher", description = "Der mächtige Wolf Grünpirscher war einst ein Beschützer dieser Wälder. Er ist dunklen Mächten anheimgefallen. Mein Bruder und ich haben versucht, seinen Geist zu beschwichtigen, aber er ist zu weit entrückt.\n\nBenutzt die von mir entwickelte Bezauberung, um ihn zu schwächen. Ich bitte Euch, {class}, setzt seinem Leiden ein Ende.\n\nMein Bruder ist noch zu schwach und ich muss bleiben, um ihn zu beschützen. Geht jetzt, bevor der Wolf uns alle verschlingt!", sourceObjective = "Tötet Grünpirscher.", completion = "Eine grausige, aber notwendige Aufgabe. Ich hoffe, Grünpirschers Geist wird jetzt Frieden finden.\n\nSeid vorsichtig, {name}. Diese Wälder werden durch eine uralte Macht widernatürlich verändert.", sourceObjectiveStatus = "unverified-source-field" }
quests[50954] = { id = 50954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalar für immer!", description = "Bwonsamdi hat mir 'ne Warnung zugeflüstert: Der Feind is' in Bewegung.\n\nIch hab alles an Verteidigungsmöglichkeiten zusammengezog'n, was in der kurzen Zeit möglich war, aber wir sind gefährlich unterbesetzt.\n\nIch kann nur hoffen, dass dank Eurer Bemühungen die Loa uns heute beisteh'n werden.\n\nSeid Ihr bereit, Zandalar zu verteidig'n?", sourceObjective = "Schließt das Szenario \"Zandalar für immer\" ab.", completion = "Wir haben die Schlacht gewonnen, nich' den Krieg.", sourceObjectiveStatus = "unverified-source-field" }
quests[50955] = { id = 50955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind keine Freunde", description = "Ich habe mit Klaas Mekkel, dem Käpt'n dieser Mannschaft, eine Weile in Tol Dagor gesessen. Er liebt es, seine Männer aus dem Hintergrund zu kommandieren.\n\nWie es der Zufall will, hab ich ihn gerade auf der anderen Seite der Ebene gesehen. Wir zwei sollten ihm einen Besuch abstatten!", sourceObjective = "Beseitigt Klaas Mekkel.", completion = "Ich habe seine Katze nie leiden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[50956] = { id = 50956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taschengeld", description = "Das ist eine Menge Gold! Ich werde eine Weile brauchen, um es aufzuteilen, aber ich kann Euch schon mal etwas in die Hand geben, damit Ihr über die Runden kommt, bis ich fertig bin.\n\nKommt morgen wieder, vielleicht habe ich es bis dahin geschafft.", sourceObjective = "Nehmt das Geld.", completion = "<Ein kleiner Vorschuss von Leo als Anteil an der Beute.>", sourceObjectiveStatus = "unverified-source-field" }
quests[50957] = { id = 50957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rezans Zorn" }
quests[50958] = { id = 50958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Achtet auf Eure Geldbörsen" }
quests[50959] = { id = 50959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plündernde Piraten" }
quests[50960] = { id = 50960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harlans Befehle", description = "<Zwischen den Seiten des Logbuchs des Kapitäns steckt ein Brief mit dem Siegel von Harlan dem Schmierigen.\n\nOffenbar hat der Schmierige diesen Piraten befohlen, dem Hause Kronsteig weiteren Ärger zu bereiten.\n\nLuzilla sollte umgehend darüber informiert werden!>", sourceObjective = "Bringt Harlans Befehle zu Luzilla Kronsteig in Drustvar.", progress = "Was habt Ihr für mich, Festländer?", completion = "<Luzilla liest die Befehle.>\n\nDieser Pirat will also das Haus Kronsteig destabilisieren? Als ob wir nicht schon genug Probleme hätten!\n\nIch danke Euch, dass Ihr mich darauf aufmerksam gemacht habt, {class}. Wie es scheint, ist der Zirkel nur der Anfang der Probleme von Kul Tiras...", sourceObjectiveStatus = "unverified-source-field" }
quests[50961] = { id = 50961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet unsere Schriftrollen!" }
quests[50962] = { id = 50962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frachtrückforderung" }
quests[50963] = { id = 50963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von finsteren Taten und finsteren Tagen", description = "Ich hätt's besser wissen müss'n. Jetzt ist Rezan tot und ich bin selbst fast am Ende meiner Kräfte. Bald wird Bwonsamdi höchstpersönlich kommen, um mich zu hol'n.\n\nTalanji... Sie muss erfahr'n, was hier geschehen is'. Geht zu ihr und erzählt's ihr. Helft ihr, wo Ihr nur könnt.\n\nIch bin 'nem Gott der Stärke gefolgt und hab dennoch nicht die Kraft, ihr mit dieser Schande in die Augen zu seh'n.\n\nJetzt muss ich unsere Streitkräfte zusammenruf'n und Zul verfolg'n.", sourceObjective = "Sprecht mit Prinzessin Talanji in den königlichen Gemächern von Dazar'alor.", completion = "Rezan ist... tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[50964] = { id = 50964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritueller Kampf" }
quests[50965] = { id = 50965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das, was bleibt", description = "<Die Runen auf der hölzernen Plakette leuchten schwach vor uralter Magie. Sie scheint Teil einer größeren Aufzeichnung zu sein.>\n\n<Vielleicht kann einer der Dornsprecher bei Schwallers Bauernhof Euch sagen, was das ist.>", sourceObjective = "Sammelt 8 Eschenwaldrelikte.", progress = "Benötigt Ihr noch etwas?", completion = "Das sind einige der verbliebenen Relikte meines Volks. Ich dachte, sie wären verloren. Ihr habt meine tiefste Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[50966] = { id = 50966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Putzkolonne" }
quests[50967] = { id = 50967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Wald vermisst", description = "Mein Lehrling Amalie und ich haben uns den Schutz dieser Wälder zur Aufgabe gemacht. Wir waren kurze Zeit nicht in Drustvar und bei unserer Rückkehr entdeckten wir, dass der Hain erkrankt war und das umgebende Land verderbt.\n\nAmalie dachte, sie könne sich allein um die Erkrankung des Hains kümmern.\n\nEs ist schon eine Weile her, seit sie sich auf den Weg gemacht hat. Könntet Ihr Ausschau nach ihr halten, wenn Ihr im Eschenwald seid?", sourceObjective = "Findet Amalie Eichensucher.", completion = "Sie sagte, sie würde allein wieder herkommen? Immerhin ist sie unversehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[50969] = { id = 50969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallmanagement" }
quests[50970] = { id = 50970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal eines Bauern", description = "Der alte Jakob hier war einer von wenigen, die uns nie mit Misstrauen begegnet sind. Gelegentlich habe ich ihm sogar auf dem Hof geholfen und er gab mir dafür Vorräte. Es wäre ungerecht, seine Qual zu ignorieren, auch wenn wir selbst unsere Probleme haben.\n\nDie Verderbnis in ihm scheint noch im Frühstadium zu sein. Ich glaube, ich kann sie läutern.\n\nNehmt diesen Zweig und bringt ihn zu den drei Schreinen im Eschenwald. So sollte er genug Energie für mein Ritual sammeln können.", sourceObjective = "Ermächtigt den ewiglebenden Zweig.", completion = "Das Holz erinnert sich und führt uns. Das sollte genug Kraft sein, um diesem Bauern zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50972] = { id = 50972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prachtmeers Parley", description = "So sieht man sich wieder.\n\nIch... entschuldige mich dafür, wie man Euch letztes Mal behandelt hat. Ich habe Priscilla immer wie einer Schwester vertraut und...\n\n<Katherine hat einen Kloß im Hals und braucht einen Moment, um die Fassung zurückzugewinnen.>\n\nFassen wir uns kurz, denn ich werde in diesem Zustand weder Versprechen geben noch formelle Vereinbarungen eingehen.\n\nKehrt zu Euren Anführern zurück. Sagt ihnen, ich wünsche eine Unterredung.\n\nDas ist alles für den Moment. Mein Volk hat heute viel durchgemacht und ich muss über vieles nachdenken.", sourceObjective = "Meldet Euch bei Genn Graumähne im Hafen von Boralus.", completion = "Katherine ist also endlich willens, sich mit uns zu unterhalten?\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[50973] = { id = 50973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Herzens", description = "Die Weltenseele gewinnt an Kraft, {name}, aber da draußen wartet noch immer Ärger auf uns. Azerit schießt aus ihren Wunden und alle Seiten kämpfen darum und beanspruchen seine Macht für sich.\n\nIhr habt bewiesen, dass Ihr Azeroths Champion seid. Ich fühle, wie sich in Eurem Amulett, das Ihr tragt, eine große Macht regt. Ich denke, das ist der Dank für alles, was Ihr getan habt.\n\nAzeroth ruft nach uns. Sie will, dass ich Euch dabei helfe, ihrem Herzen noch mehr Kraft zu entlocken. Seid Ihr bereit?", sourceObjective = "Lasst Magni Bronzebart das Herz von Azeroth stärken.", progress = "Haltet still, während ich das Herz von Azeroth stärke.", completion = "Könnt Ihr es spüren, {name}? Das Herz von Azeroth wird stärker!\n\nIch glaube, wir können dem Amulett noch mehr von seinem Potenzial entlocken.\n\nAbsorbiert Ihr weiter alles Azerit, das Ihr findet. Ich suche derweil einen Weg, diesem Irrsinn ein Ende zu setzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[50975] = { id = 50975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritbergbau" }
quests[50976] = { id = 50976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uralter Fluch", description = "<Das raue Klima Nazmirs hat der Steintafel nicht besonders gutgetan.\n\nDer größte Teil der Inschriften ist verwittert, aber Ihr könnt ein Bild erkennen, auf dem eine von Glyphen umgebene Truhe zu sehen ist. Über der Truhe bemerkt Ihr etwas, das wie ein schwebender Schädel aussieht.\n\nUnterhalb der Bilder steht ein einzelnes Wort: \"Aiji\".\n\nDie Ruinen vor Euch wirken bedrohlich und Ihr solltet vielleicht ein paar Freunde zur Unterstützung mitnehmen.\nMit ihrer Hilfe könnt Ihr vielleicht das Geheimnis dieses \"Aiji\" lüften und den Schatz finden.>", sourceObjective = "Entzündet die Kohlenpfannen von Xal'vor und besiegt Aiji den Verfluchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[50977] = { id = 50977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmugglerrazzia" }
quests[50978] = { id = 50978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raus mit dem alten Boss", description = "Also, ich habe mit einigen Leuten gesprochen und Ihr habt mit einigen Leuten gesprochen. Niemand mag die Eisenfluträuber. Sie mindern die Profite und verscheuchen gute, ehrliche Ganov... äh, ich meine Kunden! \n\nWenn wir ihren Boss ausschalten, können wir den Rest von ihnen aus der Stadt jagen! Es wird also eine kleine Veränderung auf der Managementebene geben.\n\nEigentlich bin ich dagegen, Leute umzubringen. Ich bin eher für Liebe als für Hiebe zu haben. Aber ich kann dafür bezahlen. Wenn Ihr das für mich tut, sorge ich dafür, dass Ihr hier immer willkommen sein werdet. Wie klingt das für Euch?", sourceObjective = "Tötet Richard Schotriss.", completion = "Großartig! Jetzt bin ich der Boss in der Bucht und es gilt, was ich sage.\n\nDa Ihr mir einen guten Dienst erwiesen habt, könnt Ihr jederzeit wieder hierher zurückkommen. Vergesst nur nicht, Gold mitzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[50979] = { id = 50979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ein kleiner Schnitt", description = "Die Jungs, die bei mir zu zähen Burschen ausgebildet werden, lernen schnell!\n\nAllerdings sind sie wohl etwas... bissig, wenn sie mürrisch werden. Zu viele und mir wird ein bisschen schwindelig.\n\nDie Atrivaxpflanzen in der Nähe enthalten ein heilkräftiges Gel. Es ist sehr gut geeignet, frische Wunden zu behandeln und Gifte zu neutralisieren.\n\nSie trennen sich nur ungern davon. Könntet Ihr ein wenig davon für mich ernten?", sourceObjective = "Holt 10 Proben Atrivaxgel.", progress = "Wie läuft es mit dem Entsaften?", completion = "Danke, {name}! Das sollte ausreichen!\n\nZumindest wird es mir über die Runden helfen, bis ihnen klar wird, dass wir auf derselben Seite sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[50980] = { id = 50980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meine hungrige Nachbarin", description = "Hier gibt es eine Hydra, die beschlossen hat, die nahe gelegene Küste zu ihrem Zuhause zu machen.\n\nSie wird immer größer und gemeiner und noch hungriger!\n\nMeine Kobras haben entsetzliche Angst.\n\nBitte, {name}, kümmert Euch um sie, bevor sie uns aufs Korn nimmt!", sourceObjective = "Tötet die territoriale Hydra.", completion = "Anscheinend fand sie Euch ungenießbar. Ausgezeichnete Arbeit!\n\nWir alle danken Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[50981] = { id = 50981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Flussknospen", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Kräuterkundiger. Wir haben diese Flussknospen wirklich dringend gebraucht." }
quests[50982] = { id = 50982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Sternmoos", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Kräuterkundiger. Wir haben dieses Sternmoos wirklich dringend gebraucht." }
quests[50983] = { id = 50983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Akundas Biss", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Kräuterkundiger. Wir haben Akundas Biss wirklich dringend gebraucht." }
