quests[50988] = { id = 50988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Potential für profitable Profite", description = "Ihr seht so aus, als ob ihr schlau genug seid, eine Gelegenheit beim Schopfe zu packen, wenn sie sich bietet und rein zufällig hätte ich Euch eine anzubieten.\n\nSeht Ihr die Bucht da unten? Sie wird von Unternehmern kontrolliert, die ein Auge für die logistischen Unzulänglichkeiten haben, die in jeder Stadt einmal vorkommen können. \n\nNun, normalerweise kontrollieren sie sie. Allerdings haben sich nun ein paar Leute breitgemacht, die eher wie Söldner denken, wenn Ihr wisst, was ich meine.\n\nIhr helft mir, die Kontrolle über die Bucht zurückzubekommen, und ich sorge dafür, dass man Euch ordentlich behandelt. Klingt gut?", sourceObjective = "Trefft Euch mit Cesi Zündschnur in Jederhafen.", completion = "Also schön! Na gut, Karten auf den Tisch. Wir sind Schmuggler. Wir sind keine Piraten. Alle wollen diese Trottel in ihren roten Jacken loswerden.\n\nIhr helft mir, Boss von Jederhafen zu werden, und ich helfe Euch.\n\nSprecht mit einigen der wichtigen Leute hier. Erweist ihnen ein paar Gefallen und kommt danach zurück zu mir. Verstanden?", sourceObjectiveStatus = "unverified-source-field" }
quests[50989] = { id = 50989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Sturmsilbererz", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Bergarbeiter. Wir haben dieses Sturmsilbererz wirklich dringend gebraucht." }
quests[50990] = { id = 50990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brathühnchenwissenschaft", description = "<Vor Euch seht Ihr ein leckeres Brathühnchen... Und trotzdem kommt es Euch vor, als ob... sich in dieser Kreatur noch Leben regt.\n\nMit etwas wissenschaftlichem Glück und Geschick kann der arme Vogel vielleicht noch gerettet werden.\n\nIhr entscheidet, das Hühnchen sofort zu Dr. Glotz Widrikus in der Beutebucht zu bringen.>", sourceObjective = "Bringt das köstliche Hühnchen zu Dr. Glotz Widrikus in der Beutebucht.", completion = "Hm, das ist ein schwieriger Fall, aber ich glaube, ich kann helfen!\n\nDieser Tage geht es vielen nur noch darum, was Wissenschaft leisten können sollte, nicht, was Wissenschaft leisten kann! So, mal sehen... Ein paar Drähte und Zahnräder, ein bisschen Gefiederwachstumstrank und ein bisschen Raketensprit für den Schnellstart... Und tadaaa! Ein lebendiges und putzmunteres Roboterküken!\n\nUnd... wenn das Ding verrückt wird und alle töten will, wart Ihr nie hier und habt nie mit mir gesprochen.", sourceObjectiveStatus = "unverified-source-field" }
