quests[51001] = { id = 51001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alltägliches Schmuggelgeschäft", description = "He, wollt Ihr etwas schnelles Gold machen?\n\nWisst Ihr, ich hatte vor ein paar Wochen ein Missgeschick mit einer Lieferung. Zu viel Grog, stürmische See, plötzlich auftretende Felsen. Ihr wisst schon, immer dieselbe Geschichte.\n\nJedenfalls schwimmt meine Ladung irgendwo da draußen rum und keiner will sie für mich holen. Ist das zu glauben? Also, Ihr bringt mir meine Ladung zurück und ich zahle Euch eine großzügige Bergungsprämie.\n\nAbgemacht? Klasse!\n\nOh, äh, und passt auf die Haie auf. Hatte ich vergessen, die Haie zu erwähnen?", sourceObjective = "Sammelt 5 Schmuggelwaren aus dem Meer in der Nähe des Schiffswracks nahe Jederhafen.", progress = "Habt Ihr die Waren bekommen?", completion = "Hey, danke! Bisschen feucht, aber noch brauchbar.", sourceObjectiveStatus = "unverified-source-field" }
