quests[51015] = { id = 51015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsauftrag: Tiefseesatin", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, Schneider. Wir haben diesen Tiefseesatin wirklich dringend gebraucht." }
quests[51016] = { id = 51016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach weiterem Wissen", description = "Ich gebe es ja nur ungern zu, aber auch ich weiß nicht alles über Pflanzen. Ich habe Euch alles gelehrt, was ich über das Ankerkraut weiß, doch ich glaube, ich weiß, wie Ihr noch mehr darüber erfahren könnt. Leider müsst Ihr dazu zum Kronsteiganwesen, und das ist in letzter Zeit voller Monster.\n\nFalls Ihr in diesem Anwesen landet, seht Euch nach einem Buch mit dem Titel \"Abhandlung über Ankerkraut\" um. Sein Autor hat Jahrzehnte damit verbracht, das verfluchte Unkraut zu untersuchen.", sourceObjective = "Besorgt die Abhandlung über Ankerkraut aus dem Kronsteiganwesen.", progress = "Habt Ihr das Buch besorgt?", completion = "Ausgezeichnet! Und auch noch in so gutem Zustand! Dann schauen wir mal, ob sich darin etwas finden lässt, das Euch hilft.\n\n<Es vergeht eine kleine Weile, während Derick aufgeregt vor sich hin redet.>\n\nAha! Da haben wir es ja! Die Samenhülsen öffnen sich, wenn die Pflanze gestört wird. Wenn sie jedoch erst an den Wurzeln abgeschnitten wird, geht der Wasservorrat verloren, der zum Öffnen und Schließen der Hülsen benötigt wird. Also beginnt einfach unten und arbeitet Euch dann hoch. So solltet Ihr eine bessere Ernte erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[51017] = { id = 51017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Vorräte: Moneliterz", progress = "Seid Ihr hier, um Vorräte abzuliefern?", completion = "Danke für Eure Hilfe, {class}. Wir haben dieses Moneliterz wirklich dringend gebraucht." }
quests[51018] = { id = 51018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen eines Freundes", description = "He, Ihr habt doch Cesi geholfen und da dachte ich, dass Ihr mir vielleicht auch helfen könnt.\n\nAlso, äh, seht Ihr Frollein Duftblüte da drüben? Süß wie Honig, blitzgescheit und kocht wie eine Göttin.\n\nIch bin nicht grade ein Adonis, aber die Dame wird mir vielleicht wohlgesonnen sein, wenn ich sie mit einem Geschenk überraschen könnte. Einem wirklich großartigen Geschenk! Aber ich darf meinen Posten nicht verlassen, weil diese blöden Rotjacken sonst mit den Waren abhauen könnten.\n\nUnd da kommt Ihr ins Spiel. Findet heraus, was Frollein Duftblüte mag, besorgt es und bringt es mir.", sourceObjective = "Fragt Xun Xun Duftblüte, was sie möchte, und besorgt es in Jederhafen.", progress = "Habt Ihr etwas gefunden?", completion = "Das wollte sie haben?\n\n<Kane öffnet den Krug einen Spalt weit. Sofort stehen ihm die Tränen in den Augen.>\n\nD-Danke.\n\n<Hustend verschließt Kane hastig den Krug wieder.>\n\nDas muss sehr teuer gewesen sein. Lasst mich Euch ein Trinkgeld geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51019] = { id = 51019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie hat, worauf es ankommt", description = "Es heißt, Ihr sucht nach Unterstützung für Zündschnur. Hm, ich wäre dabei, wenn Ihr mir helft. Sie haben mir meine arme Mathilde weggenommen! \n\nBoss Schotriss sagt, ich hätte zu viel getrunken und sie beim Kartenspiel verloren. Ich kann mich nicht mehr an viel von letzter Nacht erinnern, aber ich vertrage schon so einiges und ich würde niemals meinen Vogel als Einsatz anbieten! Das riecht nach faulen Tricks. Man mag es ihr nicht ansehen, aber Mathilde ist der verdammt nochmal schnellste Falke weit und breit.\n\nDa sie mich beobachten, müsst Ihr gehen und sie befreien. Sie wird an einen sicheren Ort fliegen, wo ich sie später holen gehen kann. Abgemacht?", sourceObjective = "Befreit den Falken Mathilde.", completion = "Hah! Habt Ihr sie wegfliegen sehen? Schnell wie der Wind!\n\nIch danke Euch, {name}. Ihr und Cesi könnt auf meine Unterstützung zählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51020] = { id = 51020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halsabschneiderische Geschäftspraktiken", description = "Ich habe früher hier das Gasthaus geleitet. War eine ziemlich schöne Zeit. Ich bekam eine Menge gutes Zeug als Erste in die Hände und der beste Tratsch und alle Informationen liefen über meine Theke.\n\nUnd dann tauchte dieser Trottel Gerdt Kassendeich hier auf und warf mich raus! Der neue Boss lachte!\n\nDas sind meine letzten Silbermünzen. Die Geschäfte laufen nicht gut!\n\nIch sag Euch was. Ihr entsorgt mein Problem und ich stelle mich auf Cesis Seite. Sie würde mich niemals rauswerfen.", sourceObjective = "Tötet Gerdt Kassendeich in Jederhafen.", completion = "Wie es aussieht, braucht dieser Hafen einen neuen Gastwirt.\n\nWar mir ein Vergnügen, mit Euch Geschäfte zu machen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
