quests[51052] = { id = 51052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit für die Allianz!" }
quests[51053] = { id = 51053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tag, an dem der Hafen fiel", sourceObjective = "Benutzt das Medaillon des Ersten Maats Jamboya, um eine Vision seiner Vergangenheit zu sehen.", completion = "Das war der Ort, an dem alles begann. Ich hätt Zem'lan gleich dort aufhalt'n... un' der Mannschaft ihr Schicksal erspar'n können.\n\nStattdess'n hab ich sie gradewegs reinmanövriert.", sourceObjectiveStatus = "unverified-source-field" }
quests[51054] = { id = 51054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällige Meuterei", sourceObjective = "Befreit den Ersten Maat Jamboya.", completion = "Das wird nich' einfach, {name}. Aber das is' es wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[51055] = { id = 51055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die lange Rah des Gesetzes", description = "Ich bin nich' der einzige Pirat, den Zem'lan am Haf'n aufgehängt hat. Das Aufhäng'n an der Rah is' seine Lieblingsbestrafung für die Mannschaft.\n\nWir spür'n keinen Schmerz un' bleib'n nich' tot, also hat er nich' so viele Möglichkeit'n.\n\nSucht in der Stadt nach weiteren Aufgehängt'n. Sagt ihnen, dass sie mich hier treff'n soll'n, nachdem Ihr sie befreit habt.\n\nSie häng'n da schon wochenlang rum und wurd'n vom Rest der Mannschaft verspottet un' misshandelt. Ich wette, dass sie für Meuterei 'n off'nes Ohr ham werd'n.", sourceObjective = "Befreit Quartiermeister Tulmac, Kanonierin Bosanya und Jukanga die Petze.", completion = "Offenbar sin' wir alle der gleich'n Meinung. Meuterei!", sourceObjectiveStatus = "unverified-source-field" }
quests[51056] = { id = 51056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein letzter Tag im Leben", description = "Der Fluch kam eines schicksalshaft'n Tages vor viel'n Zeitaltern über uns, als die Sethrak angriffen. Ihre Angriffe nahmen kein Ende.\n\nIn unsrer Verzweiflung half ich Piratenkönig Zem'lan, das Undenkbare zu tun.\n\nWir wurd'n zu Monstern. Un' noch schlimmer, wir wurd'n auf ewig zu Sklav'n von Zem'lan.\n\nDer Fluch lastet schwer auf mir, aber meine Schuld noch schwerer. Ich hab meine Mannschaft da reinmanövriert.\n\nBevor wir den Piratenkönig selbst angreif'n, müsst Ihr versteh'n, mit was wir es hier zu tun ham.\n\nIhr müsst seh'n, was an dem Tag geschah, als der Haf'n von Zem'lan fiel.", sourceObjective = "Benutzt das Medaillon des Ersten Maats Jamboya, um Visionen seiner Vergangenheit zu sehen.", completion = "Jetzt wisst Ihr, wie verzweifelt wir an diesem Tag war'n, {name}.\n\nDas soll keine Entschuldigung sein. Ihr sollt nur versteh'n, warum wir getan hab'n, was wir getan hab'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51057] = { id = 51057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Feuer zurückgelassen", description = "Wenn wir Piratenkönig Zem'lan angreif'n woll'n, müss'n wir zur Goldenen Insel segeln.\n\nWir müss'n sichergeh'n, dass uns der Rest der Mannschaft nich' folgen kann, wenn wir aufbrech'n. Brennt ihre Boote im Haf'n nieder.", sourceObjective = "Benutzt die immerwährende Fackel, um 8 Plünderkanus niederzubrennen.", completion = "Gut. Wir sin' bereit loszusegeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[51059] = { id = 51059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goldene Insel", description = "Piratenkönig Zem'lan wohnt nich' mehr mit'm Rest von uns im Haf'n. Nein, er is' sich jetz' zu fein, um sich noch mit uns abzugeb'n.\n\nUm ihn zu find'n, müss'n wir zur Goldenen Insel raussegeln. Das is' die verbot'ne Insel, auf der Zem'lan alle Schätze hortet, die wir erbeutet un' geplündert ham, un' an denen er sich jetz' ganz allein ergötzt.\n\nSpringt in mein Boot, dann rudern wir da zusamm' hin.", sourceObjective = "Fahrt in Jamboyas Boot raus zur Goldenen Insel.", completion = "Wir sin' da. Das is' die Goldene Insel. Sie is' wunderschön, nich' wahr?\n\n'n richtiges Piratenparadies.", sourceObjectiveStatus = "unverified-source-field" }
quests[51060] = { id = 51060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Anteil an der Beute", description = "Diese Schätze gehör'n der Mannschaft! Wir ham für Zem'lan unzählige Schlacht'n geschlag'n, aber er will die Beute ganz für sich allein.\n\nUnd wenn wir uns was davon nehm' woll'n, verwandelt er uns in einen seiner Goldsklav'n. Das sin' diese hirnlos'n Drohnen, wie Ihr sie hier um die Schätze schleich'n seh'n könnt.\n\nAber nach der Meuterei werd'n wir hier keinesfalls mit leer'n Händ'n abzieh'n. Sammelt von den Schätzen ein, was Ihr könnt!\n\nUn' achtet auf die verflucht'n Teile. Uns könn' die nix anham, aber Euch wahrscheinlich schon.", sourceObjective = "Sammelt 12 Teile von Zem'lans verfluchten Schatz.", progress = "Mehr Schätze!", completion = "Ich schätz, das bisschen Gold wird Euch nich' allzu lange verfluch'n. Den Rest behalt ich lieber.", sourceObjectiveStatus = "unverified-source-field" }
quests[51061] = { id = 51061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als ich zum ersten Mal starb", description = "Das is' es. Da hat Zem'lan uns alle verflucht.\n\nEs begann mit mei'm Tod. Dem erst'n von unzählig'n weiteren Toden seit damals. Un' bei jedem hab ich für Piratenkönig Zem'lan un' seine selbstsüchtige Horterei von Schätz'n gekämpft un' bin dafür gestorb'n.\n\nIch weiß nich' mal, ob wir die Götz'n, mit denen er uns verflucht hat, überhaupt zerstör'n könn'. Aber versuch'n müss'n wir's. Lasst sie uns zum Altar bring'n un' seh'n, ob wir einen zerschlag'n könn'.", sourceObjective = "Stellt die Götzen auf den Altar und versucht, sie zu zerstören.", completion = "Ich fürchte, die Götzen lass'n sich nich' zerstör'n... Auch nich' durch Sterbliche. Knifflige Angelegenheit, diese Flüche.\n\nIch war der Erste, den Zem'lan verfluchte, un' ich hab nix getan, um zu verhindern, dass er den Rest der Mannschaft verflucht.\n\nIch bedaure das jed'n einzelnen Tag...\n\nAber genug von der Vergangenheit. Die Zeit der Freiheit is' gekomm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51062] = { id = 51062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zem'lan entkommen", description = "Mit einer Sache hatte Piratenkönig Zem'lan recht: Er wird nich' lang tot bleib'n.\n\nWir müss'n uns den Schatz schnapp'n un' verschwind'n, solang wir 'ne Chance ham.\n\nWir könn' das Boot nehm'n, aber wir müss'n 'nen Ort find'n, an dem wir uns 'ne Weile versteck'n könn'. Wär'n Eure Vulperafreunde bereit, 'n paar Leute zu schmuggeln?\n\n<Der Erste Maat Jamboya weist auf die Schatzhaufen in seinem Boot.>\n\nNatürlich könn' wir sie für ihre Unannehmlickeit'n entschädig'n.", sourceObjective = "Fahrt mit Jamboyas Boot zur Küste und führt die Piraten zum Letztwindlager.", completion = "In was habt Ihr uns da hineingezogen, {name}? Wir hatten Euch gebeten, unseren Freund zu finden, aber nicht, Monster in unser Lager zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51064] = { id = 51064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritwunden" }
quests[51069] = { id = 51069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Dunkelsprecher Jo'la", description = "Gesucht wegen grässlicher Verbrechen an den Zandalari: Dunkelsprecher Jo'la\n\nBesiegt diesen mächtigen Anhänger von Zul und Ihr werdet fürstlich belohnt werden.", sourceObjective = "Tötet Dunkelsprecher Jo'la.", completion = "Dieser Troll hat nix als Ärger gemacht. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[51071] = { id = 51071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Kaiserin der Säbelhauer", description = "An jeden und alle, die mutig genug sind, eine Herausforderung zu suchen: \n\nFindet und besiegt eine wilde Kaiserin der Säbelhauer, die stärkste und wildeste aller Säbelhauer in Zuldazar.\n\nMan findet sie entlang der Straße, die vom Lianendorf wegführt.\n\nJeder, der Erfolg hat, erhält eine Belohnung!", sourceObjective = "Tötet eine Kaiserin der Säbelhauer.", completion = "Danke, Champion. 'ne Bedrohung weniger für diese Gegend.", sourceObjectiveStatus = "unverified-source-field" }
quests[51072] = { id = 51072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Alpha der Eisenknöchel", description = "An jeden und alle, die mutig genug sind, eine Herausforderung zu suchen:\n\nFindet und besiegt einen Alpha der Eisenknöchel, den größten und gefährlichsten aller wilden Gorillas.\n\nMan findet sie entlang der Straße, die vom Lianendorf wegführt.\n\nJeder, der Erfolg hat, erhält eine Belohnung!", sourceObjective = "Tötet einen Alpha der Eisenknöchel.", completion = "Ihr habt diesen Eisenknöchel ausm Weg geräumt? Das bedeutet uns 'ne Menge. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[51081] = { id = 51081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syrawon die Herrin" }
quests[51082] = { id = 51082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenlager", description = "In der Mine wehen die Hordenbanner und unsere Peons stellen die Versorgung mit Eisen sicher.\n\nMit diesem Schlüssel kann die Truhe geöffnet werden. Vergewissert Euch, dass er noch funktioniert.", sourceObjective = "Benutzt den schweren Eisenschlüssel, um das Eisenlager zu öffnen.", completion = "Hehe, freut mich, dass er noch funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[51084] = { id = 51084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkler Chronist" }
quests[51085] = { id = 51085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Dunkler Chronist", description = "Champion für eine Expedition in die Tiefen von Xibala gesucht. \n\nUnsere Arbeiter fürchten sich vor den seltsamen Geräuschen und dem Wehklagen, die nachts von den Knochen ertönen. \n\nWer die Quelle der Geräusche findet und ausschaltet, dem winkt eine Belohnung.", sourceObjective = "Tötet den dunklen Chronisten.", completion = "In den Ruinen ist es jetzt nachts wieder still.", sourceObjectiveStatus = "unverified-source-field" }
quests[51086] = { id = 51086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pause ist vorbei", description = "Ich habe gehört, dass einige unserer Peons während der Arbeitszeit lieber schlafen, statt Eisen in der Mine zu schürfen. Unsere Vorräte dürfen nicht schrumpfen.\n\nNehmt diese Keule und bringt die faulen Peons wieder auf Kurs.", sourceObjective = "Treibt 3 faule Peons zurück an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[51087] = { id = 51087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Dunkler Chronist", description = "Champion für eine Expedition in die Tiefen von Xibala gesucht. \n\nUnsere Arbeiter fürchten sich vor den seltsamen Geräuschen und dem Wehklagen, die nachts von den Knochen ertönen. \n\nWer die Quelle der Geräusche findet und ausschaltet, dem winkt eine Belohnung.", sourceObjective = "Tötet den dunklen Chronisten.", completion = "Ein Geist? Wie furchtbar!", sourceObjectiveStatus = "unverified-source-field" }
quests[51088] = { id = 51088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Dunkelheit", description = "Wir haben Truppen mit Hauptmann Conrad nach Nazmir vorausgeschickt, um in diesem Höllendschungel einen Stützpunkt zu errichten.\n\nDie Berichte, die wir über die dortige Trollpopulation erhalten, sind... beunruhigend.\n\nUnsere Truppen sind völlig überfordert, {name}. Ich habe Brann Bronzebart gebeten, sich für den Aufbruch vorzubereiten.\n\nBegleitet Brann nach Nazmir, damit wir unsere Stellung dort sichern können. Die Erlösenden Winde, unser Schiff, steht für Euch bereit.", sourceObjective = "Begleitet Brann zur Siegesfeste in Nazmir.", completion = "Ich habe mit dem Tod gerungen, {race}. Es war der unspannendste Kampf, den Ihr Euch nur vorstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[51089] = { id = 51089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Tojek", description = "<Dies scheint eine Liste der Bedrohungen in unmittelbarer Nähe zu sein, doch ein wütendes Gekritzel erregt Eure Aufmerksamkeit.>\n\nWer's schafft, die Kreatur Tojek zu töt'n, dem versprech ich 'ne Belohnung aus Gold. Es heißt nich' umsonst Auge um Auge! \n\n- Rovash", sourceObjective = "Macht Jagd auf Tojek.", completion = "Hah! Er is' tot? Wirklich? Das is' großartig!\n\nHier is' Eure Belohnung. Ihr habt sie verdient!", sourceObjectiveStatus = "unverified-source-field" }
quests[51090] = { id = 51090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das malerische Anwesen der Norwinsens" }
quests[51091] = { id = 51091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Ten'gor und Nol'ixwan", description = "An alle der Herausforderung würdigen Jäger: \n\nFindet und tötet das riesige Terrorhorn Nol'ixwan und den Teufelssaurier Ten'gor. \n\nIhr unablässiger Kampf gegeneinander stört den Reiseverkehr in ganz Zuldazar. \n\nDem Sieger winkt großer Ruhm!", sourceObjective = "Tötet Nol'ixwan und Ten'gor.", completion = "Seit ewig'n Zeit'n kämpf'n die zwei schon um die Vorherrschaft. Sie werd'n die Dschungel von Zandalar nicht länger stör'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51092] = { id = 51092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malerisches Boralus" }
quests[51095] = { id = 51095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschmähne" }
quests[51096] = { id = 51096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azer'tor" }
quests[51097] = { id = 51097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgeblähter Krolusk" }
