quests[51100] = { id = 51100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riesiger Sandschnapper" }
quests[51101] = { id = 51101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verwundete König", description = "Ich habe die Dinge hier unter Kontrolle... fürs Erste jedenfalls.\n\nWenn wir diese Situation retten wollen, muss Rastakhan überleben. Habutu ist tot, aber von der anderen Wächterin, Zolani, gibt es Neuigkeiten.\n\nSie wacht in einem kleinen Fischerdorf namens Zeb'ahari über den König. Findet Zolani und tut, was in Eurer Macht steht, um Rastakhans Überleben zu sichern.\n\nPasst auf Euch auf, {name}.", sourceObjective = "Trefft Zolani in Zeb'ahari.", completion = "Es is' gut, dass Ihr gekomm'n seid. Der König liegt im Sterb'n un' uns bleibt nich' viel Zeit, was dageg'n zu unternehm'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[51102] = { id = 51102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kamid der Fallensteller" }
