quests[51109] = { id = 51109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbrannte Erde" }
quests[51111] = { id = 51111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König oder Beute?", description = "Mein Loa hielt es für angebracht, meine Entschlossenheit infrage zu stell'n.\n\nFür mein Volk, meinen Stolz und meinen Glauben werd'n wir das wieder in Ordnung bring'n. Kehrt zurück zu Eurer Horde. Ihr werdet Eure Truppen in Bereitschaft versetzen un' ich die meinen.\n\nWenn die Zeit gekommen is', werden wir gegen diese falsche Schlange Zul zurückschlag'n.", sourceObjective = "Kehrt zu Baine in den Königlichen Gemächern zurück.", completion = "Ihr habt unsere kühnsten Erwartungen übertroffen!\n\nIch bin Euch dankbar, {name}, dass Ihr für die Ehre der Horde einsteht. Wir müssen uns darauf besinnen, wer wir waren, um zu erkennen, wozu wir werden können.", sourceObjectiveStatus = "unverified-source-field" }
