quests[51127] = { id = 51127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außer Kontrolle" }
quests[51129] = { id = 51129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zweifelhafte Opfergabe", description = "Ich bin mir nicht sicher, wie klug Hauptmann Conrad ist.\n\nUnsere eigenen Leute mit Opfergaben zu diesen Bluttrollfledermäusen zu schicken?\n\nIrgendwas daran stinkt mehr als eine Achselhöhle nach einer Kneipenschlägerei.", sourceObjective = "Nehmt eine Fledermaus von der Siegesfeste nach Zalamar in Nazmir.", completion = "Für so einen tiefen Fall bin ich nicht gemacht! Der einzige Teil von mir, der mir nicht wehtut, ist mein Hut!", sourceObjectiveStatus = "unverified-source-field" }
quests[51130] = { id = 51130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerit für die Horde!" }
quests[51131] = { id = 51131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Absolut barbarisch" }
quests[51134] = { id = 51134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Knochen sprechen könnten", description = "<Offenbar erheben sich diese Skelette aus den uralten Ruinen, mit denen das Land übersät ist. Ihre Knochen scheinen mit Runen bedeckt zu sein, doch hat die Verwitterung im Laufe der Zeit nur noch Fragmente davon zurückgelassen.\n\nWenn Ihr einige noch intakte Runen finden könntet, könnte Luzilla sie vielleicht entschlüsseln und herausfinden, wo diese Skelette herkommen...\n\n...und was ihren Frieden gestört hat.>", sourceObjective = "Beschafft einen makellosen runenverzierten Knochen von einem erwachten Toten auf der Gebirgshöhe.", progress = "Was ist das denn?", completion = "Diese Zeichen... Das ist die Sprache der Drust!\n\nDie Magie des Zirkels muss die Ruhe ihrer Geister gestört und sie in unsere Welt gezogen haben, damit sie erneut gegen uns kämpfen!\n\nDas ist beunruhigend... aber es ist auch ein weiterer Grund dafür, dem Herzbannzirkel ein Ende zu bereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[51139] = { id = 51139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Tojek", description = "<Das zerfledderte Papier scheint eine Liste bekannter Bedrohungen in dieser Gegend zu enthalten.\n\nGanz oben auf der Liste steht: \"Tojek - Terrorhorn - Verantwortlich für die Beschädigung von 3 Fahrzeugen und 6 Vorratskisten sowie für den tragischen Verlust von Garrick Schwarzstahls Maulwurfmaschine. Auf jeden Fall meiden!\"\n\nVielleicht könnt Ihr diese Kreatur erlegen, um weitere Angriffe zu verhindern.>", sourceObjective = "Macht Jagd auf Tojek.", completion = "Ihr habt das verdammte Terrorhorn erledigt? Fantastisch! Vielleicht kann ich jetzt meine Maschine irgendwann wieder neu bauen!\n\nIch danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[51140] = { id = 51140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Reichtum teilen", description = "<Es mag alt und voller Schlamm sein, doch es ist und bleibt Gold und noch dazu ein ordentlicher Haufen davon! Nantes legendärer verlorener Schatz mag es nicht sein, aber es handelt sich trotzdem noch um Tausende von Goldmünzen.\n\nEin bedeutender Fund, der schnell zu Schilders zurückgebracht werden sollte, damit alle Arbeiter etwas davon erhalten.>", sourceObjective = "Bringt das Gold zu Schilders.", completion = "Einige Leute wären einfach damit abgehauen, aber Ihr nicht! Das werden wir in zweihundertvierzehn Teile aufteilen. Hier habt Ihr Euren Anteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[51142] = { id = 51142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nervige Schädlinge", description = "Verdammt noch mal! Diese Rattengesichter stehlen aus all unseren Vorräten! Was man nicht anbindet, wird einfach weggeschnappt... und manchmal wird sogar das Seil mitgeschleppt!\n\nIhr wollt die Kriegsanstrengungen in Zandalar unterstützen? Dann beseitigt so viele von diesen Mistkerlen, wie Ihr findet.\n\nWenn nicht, verschwindet!", sourceObjective = "Tötet 8 diebische Schnapper in den Allianzdocks.", completion = "Ein Dieb, der von Dieben stehl'n will?", sourceObjectiveStatus = "unverified-source-field" }
quests[51144] = { id = 51144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel Felle", description = "Ihr da! Kommt Ihr zufällig an Haderfurt vorbei?\n\nIch muss dort etwas abliefern, aber mein gewöhnlicher Bote hat sich bei einer Reise zur Angelpunktbucht etwas eingefangen.\n\nWürdet Ihr dieses Bündel Felle für mich zu Dandy Jones in Haderfurt bringen? Ich würde ja selbst gehen, aber ich muss mich ums Geschäft kümmern.", sourceObjective = "Liefert das Bündel warme Felle an Dandy Jones in Haderfurt.", progress = "Willkommen in meinem Gasthaus! Wie kann ich behilflich sein?", completion = "Ah, meine Felle! Danke für die Lieferung. Hier draußen wird es langsam kalt und die werden unsere Betten wärmen.\n\nWenn Ihr etwas zu Essen braucht oder Euch ein wenig ausruhen möchtet, werdet Ihr Euch bei mir wohlfühlen!", sourceObjectiveStatus = "unverified-source-field" }
quests[51145] = { id = 51145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluch von Jani", description = "<Dieb und Mörder/Diebin und Mörderin>, hört mich an. Ihr steht vor dem Patron der Sammler, dem Fürst'n der Diebe, dem Gott des Mülls, dem Herrscher über Gesindel un' dem Wahrer der Geheimnisse.\n\nIhr steht vor mir in einem Gewand, so kostbar wie das Gold mehrerer Königreiche, un' mit Waffen, die mehr kost'n' als meine treuesten und angesehensten Anhänger in ihrem ganz'n Leb'n verdien'n.\n\nScheint mir ein guter Zeitpunkt, Euch eine Lektion zu erteil'n. Jetzt könnt Ihr in all Eurer Macht un' Pracht erfahren, wie es ist, im Müll wühl'n zu müssen.", sourceObjective = "Überlebt die Prüfung des Jani.", completion = "Haha, gut gemacht, reicher Fremder. Haltet in diesem Land die Augen off'n. Könnt passier'n, dass Euch eins meiner Kinder auf 'nen interessanten Ort hinweist.", sourceObjectiveStatus = "unverified-source-field" }
quests[51146] = { id = 51146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kua'fon macht blau", description = "Wisst Ihr, ich glaub ja, dass sich Kua'fon irgendwie einsam fühlt, wenn Ihr nich' hier seid.\n\nWarum ich das sag? Na ja, ich hab 'ne Schriftrolle von 'nem wütenden Tortollaner gekriegt, der behauptet, dass ihm Kua'fon Glitzerzeug aus'm Laden geklaut hat, aber das kann ja sonst was bedeut'n.\n\nSolltet Ihr ihn nich' lieber aufhalt'n, bevor das noch Eur'n Ruf schädigt?\n\n<Schwingenhalter Goja kichert.>", sourceObjective = "Haltet Kua'fon davon ab, im Hafen von Zandalar Unsinn zu treiben.", completion = "<Kua'fon stößt Euch mit dem Kopf entschuldigend an.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[51147] = { id = 51147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kua'fon macht blau", description = "Von der Terrasse der Auserwählten kam 'n Bote. Es ging schon wieder um Eur'n Begleiter.\n\n<Schwingenhalter Goja schmunzelt.>\n\nOffenbar schafft'n es nich' mal die Priester von Pa'ku, ihn davon zu überzeug'n, zu geh'n. Ihr solltet geh'n un' ihn zurück nach Hause hol'n, wo er hingehört.", sourceObjective = "Findet Kua'fon auf der Terrasse der Auserwählten und schickt ihn nach Hause.", completion = "<Kua'fon leckt Euch mit seiner rauen Zunge über die Wange.>\n\nSkrii.", sourceObjectiveStatus = "unverified-source-field" }
quests[51149] = { id = 51149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Hafen vergessen", description = "Beim Verladen der aktuellen Lieferung für die Südwindstation gab es ein kleines Missgeschick. Es wurden wohl Papiere vergessen, die für den Dockmeister bestimmt waren.\n\nOhne die kann er die Lieferungen nicht an die Boten weitergegeben, doch die nächste Frachtfähre legt nicht so bald ab. Meint Ihr, Ihr könntet sie zu Fuß überbringen? Das Dock für die Fähren befindet sich nur einen kurzen Ausflug die Straße runter.", sourceObjective = "Liefert das Paket bei Dockmeister Tinsen ab.", completion = "Ich hatte mich schon gewundert, wo die waren. Ich danke Euch vielmals.", sourceObjectiveStatus = "unverified-source-field" }
quests[51150] = { id = 51150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrung der Gefallenen", description = "Eine schändliche Lage. Unentschuldbar! Die Soldaten haben keine Opfergaben zu den Bluttrollen gebracht, sie WAREN die Opfergaben!\n\nWäre eine schwere Aufgabe, sie in diesem Loch ordentlich beizusetzen. Uns bleibt wohl nur, ihre Erkennungsmarken zu sammeln.\n\nArme Burschen und Mädels.", sourceObjective = "Sammelt 7 Erkennungsmarken von Soldaten der Siegesfeste.", completion = "Die Marken werde ich behalten und ihren Familien überbringen. Aber reden wir nicht über die Umstände ihres Todes, ja? Wir müssen nicht noch mehr Trauer in die Welt bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[51151] = { id = 51151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Brief an die Liga", description = "Am Resort auf dem Hügel gibt es einen Forscher, der einen Brief an die sogenannte \"Forscherliga\" senden möchte. Er meint, sie hätten in der Nähe alter Drustruinen auf der anderen Seite des Sunds ihr Lager aufgeschlagen.\n\nDort gibt es keine richtige Station, also muss der Brief durch einen Boten zugestellt werden. Würdet Ihr ihn mitnehmen, falls Ihr Euch auf diesen Weg begebt?", sourceObjective = "Findet die Mitglieder der Forscherliga im Thovasbasislager.\n\nBereitgestellter Gegenstand:", completion = "Wir haben hier vielleicht ein klitzekleines Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[51153] = { id = 51153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'fani der Verbannte" }
quests[51154] = { id = 51154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überfällig" }
