quests[51157] = { id = 51157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golanar" }
quests[51159] = { id = 51159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit den schweren Geschützen", description = "<Diese Kanone ist noch in gutem Zustand. Eine Menge Feuerkraft, um die Horde aufzuhalten.\n\nBringt sie zu Leefke Martinek. Die Kanone wird ihr bei der Verteidigung der Hütte der Eckharts sicher helfen.>", sourceObjective = "Kanone abgeliefert.", completion = "Was für eine unerwartete Überraschung!", sourceObjectiveStatus = "unverified-source-field" }
quests[51161] = { id = 51161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Za'roco", description = "An alle, die über Ehre und eine scharfe Klinge verfügen: \n\nFindet und tötet den Dieb Za'roco.\n\nVerbannte, die ihre Brüder verraten, verdienen den Tod.\n\nWer seinen Namen von der Liste streichen kann, verdient sich damit eine gebührende Belohnung.", sourceObjective = "Findet und tötet Za'roco den Gauner.", completion = "Za'roco hat bekomm'n, was er verdient hat. Und das kriegt Ihr jetz' auch!", sourceObjectiveStatus = "unverified-source-field" }
quests[51162] = { id = 51162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Taz'raka der Verräter", description = "An alle Karawanen und Reisenden:\n\nHütet Euch vor Taz'raka dem Verräter, einem Skelett, das Reisende an der Straße in der Nähe vom Hafen von Zem'lan überfällt. Wenn diese Straße auf Eurer Route liegt, umgeht die Ruinen so schnell Ihr könnt.\n\nMehrere Karawanen haben gemeinsam eine Belohnung für den Tod von Taz'raka ausgesetzt.\n\nWer diese einfordern möchte, sollte mit Norah im Letztwindlager sprechen.", sourceObjective = "Findet und tötet Taz'raka den Verräter.", completion = "Das Kopfgeld zahle ich gern. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[51164] = { id = 51164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Teilnehmer für Kobraausflug", description = "An alle Gäste des Goldhauers:\n\nEs freut uns sehr, dass wir unsere Ausflugsaktivitäten um eine überraschende Neuerung erweitern konnten!\n\nDer neue Erlebnisausflug zur unaufhaltsamen Riesenkillerkobra ist ab sofort verfügbar!\n\nAnmeldungen sind nicht erforderlich, da Ihr alle automatisch zur Teilnahme an dieser Aktivität freiwillig gemeldet wurdet.\n\nBegebt Euch zur Teilnahme einfach in die Dünen nördlich des Goldhauers und versucht, Euch nicht von der Riesenkobra töten zu lassen, die das Gebiet neuerdings durchstreift.\n\nGebietskundige Führer werden für diese Aktivität derzeit nicht angeboten. Viel Spaß!", sourceObjective = "Tötet Sevriss.", completion = "Ihr habt die Riesenschlange umgelegt? Glückwunsch!\n\nDann aktualisier ich mal besser die Ausflugsbroschüre.", sourceObjectiveStatus = "unverified-source-field" }
quests[51165] = { id = 51165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Sandspäher Vesarik", description = "An alle, die den Sturz der Treulosen erleben wollen: \n\nSandspäher Vesarik wurde auf Patrouille zwischen den Dünen im Osten gesichtet. Sammelt eine mächtige Streitmacht und bezwingt ihn!\n\nBei Erfolg erwartet Euch eine gebührende Belohnung.", sourceObjective = "Findet und tötet Sandspäher Vesarik.", completion = "Vesariks Tod wird den Treulosen einen mächtigen Schlag versetzt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[51166] = { id = 51166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bis zu den Wurzeln" }
quests[51167] = { id = 51167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut von Hir'eek", description = "Dieses gruslige Gesinge von nebenan kann nur eins bedeuten: Da will jemand Haue!\n\nIch würde Euch ja helfen, aber ich benötige noch ein paar Tränke, bevor ich wieder auf den Beinen bin.\n\nBeseitigt diese Bluthexe, dann wird die Magie sicher verschwinden.", sourceObjective = "Bezwingt Bluthexe Pakkala.", completion = "Ich hab immer gedacht, Hexen würden bei Ritualen keine Kleider tragen. Und wo war überhaupt ihr Besen?", sourceObjectiveStatus = "unverified-source-field" }
quests[51168] = { id = 51168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeloten von Zalamar", description = "Wir sind vom Feind umzingelt, {name}, und das bringt mein Blut zum Brodeln!\n\nIch fühl mich pu... wohl wie so ein fluffiger Hund... ich bin bereit, uns aus dieser verfluchten Höhle herauszuführen.\n\nSetzen wir ihren elenden Leben ein Ende, ja?", sourceObjective = "Tötet 10 Zeloten von Zalamar im Sturz.", progress = "Riecht nach... Sieg.", completion = "Die elendsten Orte der Welt sind völlig dunkle Löcher ohne ein einziges Artefakt!", sourceObjectiveStatus = "unverified-source-field" }
quests[51169] = { id = 51169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht vor dem Sturz", description = "Lasst uns aus diesem Loch verschwinden. Meine Nackenhaare wollen sich einfach nicht legen. Ich hatte ja auf Artefakte, Schätze, Haggis oder wenigstens das ein oder andere Schmuckstück gehofft.\n\nDiese Fledermäuse sehen aus, wie die, auf denen wir hergekommen sind... Hoffentlich bringen sie uns zurück zur Siegesfeste und nicht in eine verfluchte Höhle ohne den kleinsten Schatz.", sourceObjective = "Fliegt auf einer Fledermaus zur Siegesfeste.", completion = "Die Siegesfeste hat den falschen Namen. Ich finde Narrenfeste viel passender.", sourceObjectiveStatus = "unverified-source-field" }
quests[51170] = { id = 51170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hafenrundfahrt", description = "Wir brauchen den Hafen als Operationsbasis. Die Ruinen auf der anderen Seite würden diesen Zweck gut erfüllen.\n\nLeider sind sie wohl von einer feindlichen Streitmacht besetzt. Daher schicke ich Soldaten aus, um die Küste zu erobern. Ich möchte, dass Ihr sie begleitet, da Ihr über die meiste Erfahrung verfügt.\n\nIch will keinen einzigen Feind mehr sehen, wenn unsere Ingenieure ankommen.\n\nUnd jetzt geht und erobert den Hafen für die Allianz!", sourceObjective = "Erobert den Trümmersteinhafen.", completion = "Dem Licht sei Dank, dass Ihr uns begleitet habt! Gefreiter Leonhard hat es nicht geschafft und Gefreiter James wurde von den verfluchten Schlangenwesen geschnappt!\n\nAber immerhin sind die anderen von ihnen wohl geflüchtet, nachdem Ihr angefangen habt, den Tod von oben auf sie herabregnen zu lassen.\n\nMan muss sich auch über die kleinen Siege freuen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[51172] = { id = 51172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gabelblitz" }
